import tempfile
import torch
import torch.nn as nn
import torch.nn.functional as F
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    label = int(ctx.index) % 2
    features = torch.randn(4, generator=ctx.rng.torch)
    return {"inputs": synth.Tensor(features), "labels": synth.Tensor(torch.tensor(float(label)))}
dataset = synth.Spec("multi-similarity-embeddings", generator=samples, size=16, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class EmbeddingModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=3)
    def forward(self, inputs):
        return {"embeddings": F.normalize(self.network(inputs), p=2, dim=-1)}
trainer = Trainer(EmbeddingModel(), train, recipe="structured-objective", recipe_config={"loss": "multi-similarity", "bindings": {"logits_or_prediction": {"output": "embeddings"}, "targets": {"batch": "labels"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
